import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [studyLevel, setStudyLevel] = useState('Grade 10'); 
  const [formData, setFormData] = useState({ name: '', subjects: '', phone_number: '', address: '', password: 'ST@123' });

  // 🟢 Grade සහ A/L Stream එක අනුව විෂයයන් වෙනස් වෙන Logic එක
  const getSubjectsForLevel = (level) => {
    if (level.includes('A/L (Science/Maths)')) return ['Combined Maths', 'Biology', 'Physics', 'Chemistry', 'Agriculture'];
    if (level.includes('A/L (Commerce)')) return ['Accounting', 'Business Studies', 'Economics', 'Business Stats', 'IT'];
    if (level.includes('A/L (Arts)')) return ['Sinhala', 'Political Science', 'Geography', 'History', 'Logic', 'Languages'];
    if (level.includes('A/L (Technology)')) return ['SFT', 'ET', 'BST', 'IT'];
    
    // Grade 6 ඉඳන් 11 වෙනකම් O/L විෂයයන්
    return ['Mathematics', 'Science', 'English', 'History', 'Sinhala', 'Buddhism', 'ICT', 'Commerce', 'Health & PE', 'Art', 'Dancing', 'Music']; 
  };

  const fetchStudents = () => {
    // ORDER BY id DESC නිසා අලුත් ළමයි උඩින්ම එනවා
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Grade එකට තෝරපු Level/Stream එක දාලා Database එකට යවනවා
    const finalData = { ...formData, grade: studyLevel };

    axios.post('http://localhost:8081/api/add-student', finalData)
      .then(res => {
        if(res.data.status === "Success") {
            fetchStudents(); 
            setFormData({ name: '', subjects: '', phone_number: '', address: '', password: 'ST@123' });
            setShowAddForm(false);
            alert("✅ Student added successfully!");
        }
      });
  };

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8fafc', minHeight: '100vh', position: 'relative' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <h2 style={{ color: '#15803d', margin: 0 }}>Manage Students</h2>
        <button onClick={() => setShowAddForm(true)} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add New Student</button>
      </div>
      
      {showAddForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', width: '500px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' }}>
            <h3 style={{ marginTop: 0, color: '#334155', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Add New Student</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
              <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              
              <div style={{ display: 'flex', gap: '10px' }}>
                  {/* 🟢 Grade ද A/L Stream එකද කියලා ලස්සනට තෝරන කොටුව */}
                  <select value={studyLevel} onChange={(e) => { setStudyLevel(e.target.value); setFormData({...formData, subjects: ''}); }} style={{...inputStyle, flex: 1}}>
                      <optgroup label="O/L Classes">
                          {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11'].map(g => <option key={g} value={g}>{g}</option>)}
                      </optgroup>
                      <optgroup label="A/L Streams">
                          <option value="A/L (Science/Maths)">A/L (Science/Maths)</option>
                          <option value="A/L (Commerce)">A/L (Commerce)</option>
                          <option value="A/L (Arts)">A/L (Arts)</option>
                          <option value="A/L (Technology)">A/L (Technology)</option>
                      </optgroup>
                  </select>

                  {/* 🟢 අදාළ විෂය තෝරන කොටුව */}
                  <select value={formData.subjects} onChange={(e) => setFormData({...formData, subjects: e.target.value})} required style={{...inputStyle, flex: 1}}>
                      <option value="" disabled>-- Select Subject --</option>
                      {getSubjectsForLevel(studyLevel).map(sub => <option key={sub} value={sub}>{sub}</option>)}
                  </select>
              </div>

              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              
              {/* 🟢 Address එක Optional කළා (required කෑල්ල අයින් කළා) */}
              <input type="text" placeholder="Residence Address (Optional)" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              
              <div style={{ backgroundColor: '#f0fdf4', padding: '10px', borderRadius: '8px', border: '1px dashed #22c55e', fontSize: '12px', color: '#15803d' }}>Default login password: <b>ST@123</b></div>
              
              <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={() => setShowAddForm(false)} style={{ flex: 1, padding: '12px', backgroundColor: '#e2e8f0', color: '#334155', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Cancel</button>
                <button type="submit" style={{ flex: 1, padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Save Student</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div style={{ backgroundColor: 'white', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', overflow: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '900px' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr><th style={thStyle}>Full Name</th><th style={thStyle}>Grade / Stream</th><th style={thStyle}>Main Subject</th><th style={thStyle}>Phone</th><th style={thStyle}>Address</th></tr>
          </thead>
          <tbody>
            {students.length > 0 ? students.map((s) => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={tdStyle}><b>{s.name}</b></td>
                <td style={tdStyle}><span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold', color: '#0f172a' }}>{s.grade}</span></td>
                <td style={tdStyle}>{s.subjects}</td>
                <td style={tdStyle}>{s.phone_number || '-'}</td>
                <td style={tdStyle}>{s.address || '-'}</td>
              </tr>
            )) : <tr><td colSpan="5" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No students found.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}
const inputStyle = { padding: '12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', fontSize: '14px', whiteSpace: 'nowrap' };
const tdStyle = { padding: '15px', fontSize: '14px', color: '#475569' };
